edits.replacement:
#root #keysmodal #keyslist{ max-height:calc(100vh - var(--sp-5) * 6); }
/* v28.xx (cw-cardwide2) critic on Settings 18 after cw-cardwide (2 of 5): "the label is at x=500 and the control at x=1150 to 1400, about 650px away, keep them within 400px". Now the name column is 8 x 48 wide (384) and the stepper sits straight after it in the 960 column, so a label and its value are never more than 400px apart on the wide card. */
#root #settingsmodal #setlist .row:not(.setjump) > div:first-child{ flex:0 0 calc(var(--sp-5) * 8) !important; }
#root #settingsmodal #setlist .row:not(.setjump) > button{ margin-left:0; }

check:
{v:'VER',what:'on the wide Settings card a row stepper sits within 420 px of its label, never at the far edge of the 960 column',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], m, row, lab, st, r;
   try{
     __topClear(); __hubEnter();
     r=__station('dev','KeyE'); if(r&&r.err) return 'station: '+r.err;
     m=document.getElementById('settingsmodal');
     if(!m||!m.classList.contains('on')) return 'the settings window did not open';
     UIM.step(600);
     row=document.querySelector('#setlist .row:not(.setjump) > button'); if(!row) return 'no stepper row';
     row=row.parentNode; lab=row.firstElementChild.getBoundingClientRect(); st=row.querySelector(':scope > button').getBoundingClientRect();
     var z=parseFloat(m.style.zoom)||1;
     if(!((st.left-lab.left)<=420*z)) bad.push('the stepper starts '+Math.round((st.left-lab.left)/z)+' px from the label, want 420 or less');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
